final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid constant pool entry index");
    }
    if (charBuffer == null || charBuffer.length == 0) {
        throw new IllegalArgumentException("Invalid char buffer");
    }

    int offset = classFileBuffer[constantPoolEntryIndex + 1] << 8 | classFileBuffer[constantPoolEntryIndex + 2];
    int length = classFileBuffer[offset] & 0xFF;

    if (offset + length + 1 > classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid UTF-8 string length");
    }

    for (int i = 0; i < length; i++) {
        charBuffer[i] = (char) (classFileBuffer[offset + i + 1] & 0xFF);
    }

    return new String(charBuffer, 0, length);
}

