protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        return graph.createPath();
    }

    V startVertex = edgeList.get(0).getEndpoint(0);
    V currentVertex = startVertex;
    List<V> vertices = new ArrayList<>();
    vertices.add(currentVertex);

    for (E edge : edgeList) {
        if (edge.getEndpoint(0).equals(currentVertex)) {
            currentVertex = edge.getEndpoint(1);
        } else {
            currentVertex = edge.getEndpoint(0);
        }
        vertices.add(currentVertex);
    }

    return graph.createPath(vertices);
}

